const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const CLUBS = [
 {name:'Triestina',league:'Serie C · Girone A',level:62,budget:500,target:'Play-off',badge:'🔴',prestige:2},
 {name:'Perugia',league:'Serie C · Girone B',level:65,budget:500,target:'Promozione',badge:'⚪',prestige:3},
 {name:'Arezzo',league:'Serie C · Girone B',level:64,budget:500,target:'Play-off',badge:'🟥',prestige:3},
 {name:'Catania',league:'Serie C · Girone C',level:68,budget:500,target:'Promozione',badge:'🔴',prestige:4},
 {name:'Vicenza',league:'Serie C · Girone A',level:69,budget:500,target:'Vinci il campionato',badge:'⚪',prestige:4}
];
const OTHER_CLUBS=['Pescara','Benevento','Avellino','Ternana','Foggia','Carrarese','Lecco','Novara','Südtirol'];
const FIRST=['Luca','Marco','Andrea','Matteo','Davide','Alessandro','Nicolò','Simone','Riccardo','Federico','Gabriele','Tommaso','Enrico','Filippo','Samuele','Michele','Diego','Pietro','Youssef','Noah','Adam','Edoardo','Lorenzo','Rayan'];
const LAST=['Rossi','Bianchi','Romano','Greco','Costa','Galli','Conti','Ferrari','Esposito','Marchetti','De Luca','Marini','Moretti','Ricci','Villa','Serra','Fontana','Colombo','Mancini','Lombardi','Silva','Kovac','Ndiaye','Rinaldi'];
const POSITIONS=['POR','DC','DC','TS','TD','CC','CC','MED','ALA','ATT','ATT','POR','DC','DC','TS','TD','CC','CC','ALA','ATT','CC'];
const FORMATIONS={'4-3-3':[4,3,3],'4-4-2':[4,4,2],'3-5-2':[3,5,2],'4-2-3-1':[4,2,3,1],'5-3-2':[5,3,2]};
let game=loadGame(), activeTab='overview', squadFilter='Tutti', matchMode='normal', toastTimer;
function loadGame(){try{return JSON.parse(localStorage.getItem('rtgm-save'))}catch{return null}}
function save(){localStorage.setItem('rtgm-save',JSON.stringify(game))}
function rnd(min,max){return Math.floor(Math.random()*(max-min+1))+min}
function choice(arr){return arr[Math.floor(Math.random()*arr.length)]}
function money(n){return Math.max(0,Math.round(n)).toLocaleString('it-IT')}
function makePlayers(level,count=21){return Array.from({length:count},(_,i)=>{let pos=POSITIONS[i%POSITIONS.length],rating=Math.max(42,Math.min(83,level+rnd(-10,9)));return{id:`p${Date.now()}${i}${rnd(1,999)}`,name:`${choice(FIRST)} ${choice(LAST)}`,pos,rating,age:rnd(18,34),value:Math.round((rating-38)*2.1+rnd(2,14)),fitness:rnd(78,100),injury:0,bans:0,yellows:0,goals:0,assists:0,starter:i<11}})}
function makeLeague(team){let base=[{name:team.name,badge:team.badge,level:team.level,prestige:team.prestige},{name:'Pescara',badge:'🔵',level:67,prestige:4},{name:'Benevento',badge:'🟡',level:70,prestige:5},{name:'Avellino',badge:'🟢',level:66,prestige:4},{name:'Ternana',badge:'🔴',level:68,prestige:4},{name:'Foggia',badge:'⚫',level:62,prestige:3},{name:'Carrarese',badge:'🔵',level:63,prestige:3},{name:'Lecco',badge:'🔵',level:61,prestige:3},{name:'Novara',badge:'🔵',level:60,prestige:2},{name:'Südtirol',badge:'⚪',level:65,prestige:4}];return base.map((c,i)=>({...c,id:`club${i}`,pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0,form:[],players:makePlayers(c.level,18)}))}
function createSchedule(teams){let arr=teams.map(t=>t.id), rounds=[];for(let r=0;r<arr.length-1;r++){let matches=[];for(let i=0;i<arr.length/2;i++){let home=arr[i],away=arr[arr.length-1-i];if((r+i)%2)[home,away]=[away,home];matches.push({home,away,played:false,score:null})}rounds.push(matches);arr=[arr[0],arr[arr.length-1],...arr.slice(1,-1)]}let full=[...rounds,...rounds.map(ms=>ms.map(m=>({home:m.away,away:m.home,played:false,score:null})))];return full}
function newGame(index){let chosen=CLUBS[index],teams=makeLeague(chosen),fixtureList=createSchedule(teams),me=teams[0];game={clubIndex:index,club:chosen.name,season:2026,manager:'Il Mister',teams,schedule:fixtureList,round:0,credits:500,initialBudget:500,prestige:chosen.prestige,reputation:8,jobSecurity:100,dismissed:false,trophies:0,played:0,won:0,drawn:0,lost:0,objectives:chosen.target,objectiveMet:false,formation:'4-3-3',style:'Equilibrato',captain:me.players[5].id,squad:me.players,cup:{round:0,done:false,champion:null,fixtures:[]},news:[{icon:'📋',text:`${chosen.name} ha affidato la panchina a un nuovo volto: inizia la sfida.`,date:'OGGI',type:'club'}],history:[],lastMatch:null,match:null,window:'estiva',marketTransfers:[],retired:[],awards:[],gameOver:false};save();activeTab='overview';render();toast(`${chosen.name} ti dà il benvenuto. È ora di scrivere la storia.`)}
function currentClub(){return game?.teams.find(t=>t.name===game.club)}
function leagueTable(){return [...game.teams].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function nextFixture(){return game?.schedule[game.round]?.find(m=>m.home===currentClub()?.id||m.away===currentClub()?.id)}
function opponentOf(f){let id=f?.home===currentClub()?.id?f.away:f?.home;return game?.teams.find(t=>t.id===id)}
function goalTarget(){let pos=leagueTable().findIndex(t=>t.id===currentClub()?.id)+1;let map={'Vinci il campionato':1,'Promozione':2,'Play-off':5,'Salvezza':8};return map[game.objectives]||5}
function addNews(icon,text,type='world'){game.news.unshift({icon,text,date:`${game.season} · G${game.round+1}`,type});game.news=game.news.slice(0,32)}
function toast(msg){let el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function showModal(html){$('#modal-root')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal-root"><div class="modal">${html}</div></div>`);$('#modal-root').addEventListener('click',e=>{if(e.target.id==='modal-root')e.target.remove()})}
function render(){if(!game){renderWelcome();return}if(game.match?.active){renderMatch();return}renderShell()}
function renderWelcome(){let picks=CLUBS.map((c,i)=>`<button class="team-pick" onclick="newGame(${i})"><div class="pick-name">${c.badge} &nbsp;${c.name}</div><div class="pick-league">${c.league} · Italia</div><div class="pick-stats"><span>BUDGET<strong>500 cr</strong></span><span>OBIETTIVO<strong>${c.target}</strong></span><span>ROSA<strong>${c.level} / 100</strong></span></div></button>`).join('');$('#app').innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">↗</div><div class="brand-title">ROAD TO GLORY<span>MANAGER · 2026</span></div></div><div class="season-pill">NUOVA CARRIERA</div></header><main class="main" style="max-width:1000px;margin:auto;padding-top:55px"><div class="eyebrow">LA TUA STORIA COMINCIA QUI</div><div style="font:600 clamp(34px,6vw,60px) var(--display);letter-spacing:-.06em;max-width:760px;line-height:1.04">Dal fango dei campi di provincia, <span style="color:var(--lime)">fino alla gloria.</span></div><p style="color:#aab6ab;max-width:600px;line-height:1.7;margin:17px 0 30px">Ogni grande carriera comincia con una panchina scomoda e una rosa da plasmare. Scegli il tuo primo incarico: il resto lo scriverai tu.</p><div class="eyebrow">SCEGLI LA TUA PRIMA PANCHINA · 5 CLUB · SERIE C</div><div class="team-picks">${picks}</div><div class="muted" style="font-size:10px;margin-top:18px">Una stagione compatta: 18 giornate, mercato estivo e invernale, Coppa nazionale. La carriera si salva automaticamente.</div></main></div>`}
function renderShell(){let labels=[['overview','◫','Panoramica'],['squad','♙','Rosa & tattica'],['market','↗','Calciomercato'],['fixtures','▦','Calendario'],['table','≡','Classifica'],['cup','♜','Coppa Italia'],['news','◉','Mondo Calcio']];let nav=labels.map(([id,ic,name])=>`<button class="nav-btn ${activeTab===id?'active':''}" onclick="go('${id}')"><span class="nav-icon">${ic}</span>${name}</button>`).join('');let club=currentClub();$('#app').innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">↗</div><div class="brand-title">ROAD TO GLORY<span>MANAGER</span></div></div><div class="season-pill">STAGIONE ${game.season}/${String(game.season+1).slice(-2)}</div><div class="top-actions"><button class="icon-btn" title="Mondo Calcio" onclick="go('news')">◉<i class="badge-dot"></i></button><button class="icon-btn" title="Salva" onclick="save();toast('Carriera salvata')">▣</button><div class="manager"><div class="avatar">M</div><div><strong style="font-size:11px">${game.manager}</strong><small>${game.dismissed?'TRAGHETTATORE · ':''}Reputazione ${game.reputation} · Fiducia ${game.jobSecurity??100}%</small></div></div></div></header><div class="layout"><aside class="sidebar"><div class="side-label">IL TUO CLUB</div>${nav}<div class="side-bottom"><div class="club-mini">${club.badge} &nbsp;${game.club}</div><p>Prestigio ${'★'.repeat(Math.min(5,game.prestige))}${'☆'.repeat(Math.max(0,5-game.prestige))}<br>${game.trophies} ${game.trophies===1?'trofeo':'trofei'} in bacheca</p></div></aside><main class="main">${pageContent()}</main></div></div>`}
function pageContent(){switch(activeTab){case'squad':return squadPage();case'market':return marketPage();case'fixtures':return fixturesPage();case'table':return tablePage();case'cup':return cupPage();case'news':return newsPage();default:return dashboardPage()}}
function dashboardPage(){let club=currentClub(),table=leagueTable(),pos=table.findIndex(t=>t.id===club.id)+1,f=nextFixture(),opp=opponentOf(f),pct=Math.min(100,Math.round((game.played/18)*100)),form=club.form.slice(-5);let rows=table.slice(0,4);if(!rows.some(t=>t.id===club.id)&&pos>4)rows=[...rows.slice(0,3),club];let standing=`<table class="table"><thead><tr><th>#</th><th>Club</th><th>Pt</th><th>DR</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${t.id===club.id?'my-team':''}"><td class="rank">${table.indexOf(t)+1}</td><td>${t.badge} ${t.name}</td><td>${t.pts}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td></tr>`).join('')}<tr><td class="rank">·</td><td colspan="3" style="color:#69766a">··· zona retrocessione ···</td></tr>${table.slice(-2).map(t=>`<tr class="${t.id===club.id?'my-team':''}"><td class="rank">${table.indexOf(t)+1}</td><td>${t.badge} ${t.name}</td><td>${t.pts}</td><td>${t.gf-t.ga}</td></tr>`).join('')}</tbody></table>`;return `<div class="page-head"><div><div class="eyebrow">CENTRO DI COMANDO · ${game.season}/${game.season+1}</div><h1>Buongiorno, Mister.</h1><p>La stagione si costruisce un allenamento e una partita alla volta.</p></div><div class="date-label">GIORNATA ${Math.min(game.round+1,18)} / 18</div></div><div class="dashboard-grid"><div><section class="hero"><div class="hero-content"><div class="club-name">${club.badge} &nbsp;${game.club}</div><div class="club-meta">${CLUBS[game.clubIndex]?.league||'Serie C'} &nbsp;·&nbsp; Stagione ${game.season}/${String(game.season+1).slice(-2)}</div></div><div class="club-badge">${opp?.badge||'⚽'}</div><div class="hero-bottom"><div><div class="next-match-label">PROSSIMA PARTITA · GIORNATA ${Math.min(game.round+1,18)}</div><div class="versus">${game.club} <span>vs</span> ${opp?.name||'Fine stagione'}</div></div>${f?`<button class="hero-cta" onclick="openMatch()">PREPARA LA GARA &nbsp;↗</button>`:`<button class="hero-cta" onclick="endSeason()">CONCLUDI LA STAGIONE ↗</button>`}</div></section><div class="stats-strip"><div class="stat-card"><div class="stat-label">POSIZIONE</div><div class="stat-value">${pos}<span style="font-size:11px;color:var(--muted)"> / 10</span></div><div class="stat-sub">${form.map((r)=>`<i class="form-dot ${r==='P'?'loss':r==='N'?'draw':''}"></i>`).join('')||'Ancora nessuna gara'}</div></div><div class="stat-card"><div class="stat-label">PUNTI</div><div class="stat-value">${club.pts}</div><div class="stat-sub">${club.w}V · ${club.d}N · ${club.l}P</div></div><div class="stat-card"><div class="stat-label">ROSA MEDIA</div><div class="stat-value">${Math.round(club.players.reduce((a,p)=>a+p.rating,0)/club.players.length)}<span style="font-size:11px;color:var(--muted)"> / 100</span></div><div class="stat-sub">${club.players.length} giocatori</div></div><div class="stat-card"><div class="stat-label">CREDITI</div><div class="stat-value">${money(game.credits)}<span style="font-size:11px;color:var(--muted)"> cr</span></div><div class="stat-sub">${game.window==='estiva'?'Mercato estivo':game.window==='invernale'?'Mercato invernale':'Fuori mercato'}</div></div></div><section class="card mt-12"><div class="card-title"><h2>Ultimi risultati</h2><button class="text-link" onclick="go('fixtures')">Calendario completo ↗</button></div><div class="fixture-list">${recentFixtures()}</div></section></div><div class="right-stack"><section class="card"><div class="card-title"><h2>Obiettivo dirigenza</h2><span class="tag">${game.objectives.toUpperCase()}</span></div><div class="objective"><div class="objective-head"><strong>${game.objectives}</strong><span class="muted" style="font-size:10px">${pos}° posto</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.max(4,Math.min(100,Math.round(100-(pos/10)*100+10)))}%"></div></div><small>${game.played} gare giocate · target: top ${goalTarget()}</small></div></section><section class="card"><div class="card-title"><h2>Classifica</h2><button class="text-link" onclick="go('table')">Completa ↗</button></div>${standing}</section><section class="card"><div class="card-title"><h2>Mondo Calcio</h2><button class="text-link" onclick="go('news')">Apri feed ↗</button></div>${game.news.slice(0,2).map(n=>`<div class="news-item"><div class="news-emoji">${n.icon}</div><div class="news-copy">${n.text}<small>${n.date}</small></div></div>`).join('')}</section></div></div>`}
function recentFixtures(){let played=game.schedule.flat().filter(m=>m.played&&(m.home===currentClub().id||m.away===currentClub().id)).slice(-3).reverse();if(!played.length)return `<div class="empty-state" style="padding:16px">La stagione ti aspetta. Prepara la prima gara.</div>`;return played.map(m=>{let h=game.teams.find(t=>t.id===m.home),a=game.teams.find(t=>t.id===m.away);return `<div class="fixture-row"><div class="fixture-date">G${game.schedule.findIndex(r=>r.includes(m))+1}</div><div class="fixture-teams">${h.name} <strong>${m.score[0]} – ${m.score[1]}</strong> ${a.name}</div><div class="fixture-time">${h.id===currentClub().id?'CASA':'TRASFERTA'}</div></div>`}).join('')}
function squadPage(){let club=currentClub();return `<div class="page-head"><div><div class="eyebrow">PRIMA SQUADRA · ${club.players.length} TESSERATI</div><h1>Rosa & tattica</h1><p>Costruisci la formazione. I giocatori indisponibili non possono essere schierati.</p></div><div class="date-label">MODULO ${game.formation}</div></div><div class="content-grid"><div><section class="section-card"><div class="card-title"><h2>Lavagna tattica</h2><span class="tag">${club.players.filter(p=>p.starter).length} TITOLARI</span></div><div class="control-row mb-12"><span class="label-small">Modulo</span><select class="select-control" onchange="setFormation(this.value)">${Object.keys(FORMATIONS).map(f=>`<option ${game.formation===f?'selected':''}>${f}</option>`).join('')}</select><span class="label-small">Stile</span><select class="select-control" onchange="game.style=this.value;save();render()">${['Equilibrato','Possesso palla','Contropiede','Pressing alto','Difensivo'].map(s=>`<option ${game.style===s?'selected':''}>${s}</option>`).join('')}</select><span class="label-small">Capitano</span><select class="select-control" onchange="game.captain=this.value;save()">${club.players.map(p=>`<option value="${p.id}" ${game.captain===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div>${pitchHTML()}<div class="lineup-details"><span>Stile: <strong style="color:#c3d0c0">${game.style}</strong></span><span>Potenza XI: <strong style="color:var(--lime)">${Math.round(club.players.filter(p=>p.starter).reduce((a,p)=>a+p.rating,0)/Math.max(1,club.players.filter(p=>p.starter).length))}</strong></span></div></section><section class="section-card"><div class="card-title"><h2>Rosa completa</h2><span class="muted" style="font-size:10px">Clicca Titolare per cambiare</span></div><div class="tabs">${['Tutti','POR','DIF','CEN','ATT'].map(f=>`<button class="tab ${squadFilter===f?'active':''}" onclick="squadFilter='${f}';render()">${f}</button>`).join('')}</div>${playerList(club.players)}</section></div><aside><section class="section-card"><h2>Disponibilità</h2>${club.players.filter(p=>p.injury||p.bans).map(p=>`<div class="fixture-row"><div>${p.injury?'🩹':'🟥'}</div><div class="fixture-teams"><strong>${p.name}</strong><div class="muted">${p.injury?`Infortunio · ${p.injury} giornate`:`Squalificato · ${p.bans} gara`}</div></div></div>`).join('')||'<div class="muted" style="font-size:11px">Tutti disponibili per la prossima gara.</div>'}</section><section class="section-card"><h2>Indicazioni staff</h2><div class="news-copy">${staffTip(club)}</div><button class="text-link mt-12" onclick="autoLineup()">Schiera i migliori ↗</button></section><section class="section-card"><h2>Regole rosa</h2><div class="muted" style="font-size:10px;line-height:1.7">11 titolari · max 5 sostituzioni durante la gara.<br>Stanchezza e forma si aggiornano a ogni turno.</div></section></aside></div>`}
function positionGroup(p){return p==='POR'?'POR':['DC','TS','TD'].includes(p)?'DIF':['CC','MED'].includes(p)?'CEN':'ATT'}
function playerList(players){let shown=players.filter(p=>squadFilter==='Tutti'||positionGroup(p)===squadFilter).slice().sort((a,b)=>b.starter-a.starter||b.rating-a.rating);return `<div class="player-row header"><span></span><span>Giocatore</span><span>Ruolo</span><span>OVR</span><span>Cond.</span><span>Status</span><span></span></div>${shown.map(p=>`<div class="player-row"><span class="pos-chip">${p.pos}</span><span class="player-name">${p.name}<span class="player-sub">${p.age} anni · ${p.goals} gol</span></span><span>${p.pos}</span><span class="rating">${p.rating}</span><span class="condition ${p.fitness<60?'low':''}">${p.fitness}%</span><span>${p.injury?`<span class="danger">🩹 ${p.injury}g</span>`:p.bans?'<span class="danger">Squal.</span>':p.yellows>=3?'<span class="warn">⚠ diffidato</span>':'<span class="good">Disponibile</span>'}</span><span class="player-actions"><button class="mini-btn" onclick="toggleStarter('${p.id}')" ${p.injury||p.bans?'disabled':''}>${p.starter?'Titolare':'Panchina'}</button></span></div>`).join('')}`}
function pitchHTML(){let club=currentClub(),formation=FORMATIONS[game.formation],eligible=club.players.filter(p=>!p.injury&&!p.bans).slice().sort((a,b)=>b.starter-a.starter||b.rating-a.rating),keeper=eligible.find(p=>p.pos==='POR')||eligible[0],backs=eligible.filter(p=>['DC','TS','TD'].includes(p.pos)),mids=eligible.filter(p=>['CC','MED'].includes(p.pos)),forwards=eligible.filter(p=>['ATT','ALA'].includes(p.pos)),fill=(pool,n)=>Array.from({length:n},(_,i)=>pool[i]||eligible.find(p=>![...backs,...mids,...forwards,keeper].includes(p))||null),lines=[fill(forwards,formation.at(-1)),fill(mids,formation.length===4?formation[2]+formation[1]:formation[1]),fill(backs,formation[0]),[keeper]];return `<div class="formation-visual"><div class="pitch-line"></div>${lines.map(line=>`<div class="pitch-row">${line.map(p=>p?`<div class="pitch-player"><span class="shirt">${p.rating}</span><span>${p.name.split(' ').at(-1)}</span></div>`:`<div class="pitch-player empty"><span class="shirt">+</span><span>Da scegliere</span></div>`).join('')}</div>`).join('')}</div>`}
function staffTip(club){let avg=Math.round(club.players.reduce((a,p)=>a+p.fitness,0)/club.players.length);if(avg<68)return 'La squadra è affaticata. Ruota i titolari o usa il riposo: la freschezza incide sul rendimento.';let weak=club.players.filter(p=>p.pos==='POR').sort((a,b)=>a.rating-b.rating)[0];return `La condizione media è ${avg}%. ${weak?.rating<60?'Il reparto portieri merita rinforzi.':'Lavoro solido: continua a dare fiducia ai giovani.'}`}
function setFormation(v){game.formation=v;autoLineup(false);save();render()}
function autoLineup(notify=true){let players=currentClub().players.filter(p=>!p.injury&&!p.bans).sort((a,b)=>b.rating-a.rating);players.forEach((p,i)=>p.starter=i<11);save();if(notify)toast('Formazione migliore schierata');render()}
function toggleStarter(id){let p=currentClub().players.find(x=>x.id===id);if(!p)return;if(p.starter){if(currentClub().players.filter(x=>x.starter).length<=11){toast('Scegli prima un sostituto.');return}p.starter=false}else{let starters=currentClub().players.filter(x=>x.starter);if(starters.length>=11){let replace=starters.slice().sort((a,b)=>a.rating-b.rating)[0];replace.starter=false}p.starter=true}save();render()}
function makeMarket(){let target=currentClub().level;return Array.from({length:8},(_,i)=>{let rating=Math.max(45,Math.min(83,target+rnd(-14,12)));return{id:`m${game.season}${game.round}${i}${rnd(1,9999)}`,name:`${choice(FIRST)} ${choice(LAST)}`,pos:choice(POSITIONS),rating,age:rnd(18,31),value:Math.max(20,Math.min(190,Math.round((rating-41)*2.25+rnd(2,18)))),fitness:rnd(86,100),injury:0,bans:0,yellows:0,goals:0,assists:0,starter:false}})}
function marketPage(){if(!game.marketPool||game.marketPoolKey!==`${game.season}-${game.window}`){game.marketPool=makeMarket();game.marketPoolKey=`${game.season}-${game.window}`;save()}let candidates=game.marketPool;return `<div class="page-head"><div><div class="eyebrow">DIRETTORE SPORTIVO · ${game.window==='estiva'?'SESSIONE ESTIVA':'SESSIONE INVERNALE'}</div><h1>Calciomercato</h1><p>Scopri profili accessibili, costruisci la rosa e fai quadrare i conti.</p></div><div class="date-label">BUDGET &nbsp; <span class="good">${money(game.credits)} CR</span></div></div><div class="content-grid"><div><section class="section-card"><div class="card-title"><h2>Profili sul mercato</h2><button class="text-link" onclick="game.marketPool=makeMarket();save();render()">⟳ Aggiorna lista</button></div><p class="muted" style="font-size:10px;margin:-6px 0 14px">Una nuova sessione assegna 500 crediti. I prezzi riflettono età e livello.</p><div class="market-grid">${candidates.map(p=>`<div class="market-player"><div class="market-player-top"><div><strong>${p.name}</strong><p>${p.pos} · ${p.age} anni · ${p.rating} OVR</p></div><span class="rating">${p.rating}</span></div><div class="control-row" style="justify-content:space-between"><span class="market-price">${money(p.value)} cr</span><button class="mini-btn" onclick="buyPlayer('${p.id}')" ${game.credits<p.value?'disabled':''}>Acquista ↗</button></div></div>`).join('')}</div></section><section class="section-card"><div class="card-title"><h2>La tua rosa · cessioni</h2><span class="muted" style="font-size:10px">Incasso: 60% del valore</span></div>${currentClub().players.slice().sort((a,b)=>a.rating-b.rating).map(p=>`<div class="fixture-row"><div class="pos-chip">${p.pos}</div><div class="fixture-teams"><strong>${p.name}</strong><span class="muted"> · ${p.rating} OVR · ${p.value} cr</span></div><button class="mini-btn" onclick="sellPlayer('${p.id}')" ${currentClub().players.length<=15?'disabled':''}>Vendi ${Math.max(8,Math.round(p.value*.6))} cr</button></div>`).join('')}</section></div><aside><section class="section-card"><h2>Bilancio</h2><div class="stat-value" style="color:var(--lime)">${money(game.credits)} <span style="font-size:12px">cr</span></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,game.credits/5)}%"></div></div><div class="muted" style="font-size:10px;line-height:1.6">Budget base sessione: 500 cr<br>Top player: 100+ cr<br>Talenti di categoria: 20–80 cr</div></section><section class="section-card"><h2>Movimenti nel mondo</h2>${game.marketTransfers.slice(0,4).map(t=>`<div class="news-item"><span class="news-emoji">${t.icon}</span><div class="news-copy">${t.text}<small>${t.date}</small></div></div>`).join('')||'<div class="muted" style="font-size:10px">Il mercato si sta scaldando…</div>'}</section></aside></div>`}
function buyPlayer(id){let p=game.marketPool.find(x=>x.id===id);if(!p||game.credits<p.value)return toast('Budget insufficiente.');if(currentClub().players.length>=28)return toast('Rosa al completo (max 28).');game.credits-=p.value;currentClub().players.push({...p,id:`p${Date.now()}${rnd(1,999)}`});game.marketPool=game.marketPool.filter(x=>x.id!==id);addNews('✍️',`${game.club} chiude per ${p.name}: accordo da ${p.value} crediti.`,'transfer');save();render();toast(`${p.name} è un nuovo giocatore del club!`)}
function sellPlayer(id){let club=currentClub(),p=club.players.find(x=>x.id===id);if(!p||club.players.length<=15)return toast('Devi avere almeno 15 giocatori in rosa.');let proceeds=Math.max(8,Math.round(p.value*.6));club.players=club.players.filter(x=>x.id!==id);game.credits+=proceeds;addNews('↗️',`${p.name} lascia ${game.club}: incassati ${proceeds} crediti.`,'transfer');save();render();toast(`Cessione completata: +${proceeds} crediti.`)}
function fixturesPage(){let rows=game.schedule.map((round,i)=>{let m=round.find(x=>x.home===currentClub().id||x.away===currentClub().id),home=game.teams.find(t=>t.id===m.home),away=game.teams.find(t=>t.id===m.away);return `<div class="fixture-row" style="padding:13px 4px"><div class="fixture-date">G${String(i+1).padStart(2,'0')}</div><div class="fixture-teams">${home.badge} ${home.name} <strong>${m.played?`${m.score[0]} – ${m.score[1]}`:'vs'}</strong> ${away.name} ${away.badge}</div><div class="fixture-time">${m.played?(m.home===currentClub().id?'CASA':'TRASFERTA'):i===game.round?'OGGI':'—'}</div>${i===game.round?`<button class="mini-btn" onclick="openMatch()">Gioca ↗</button>`:''}</div>`}).join('');return `<div class="page-head"><div><div class="eyebrow">CAMPIONATO · ANDATA E RITORNO</div><h1>Calendario</h1><p>18 giornate, avversari in casa e in trasferta. Gli altri risultati sono simulati.</p></div><div class="date-label">${game.played} / 18 GARE</div></div><section class="section-card">${rows}</section><section class="section-card"><h2>La prossima sessione di mercato</h2><div class="muted" style="font-size:11px">${game.round<9?`Il mercato invernale aprirà dopo la 9ª giornata. Budget aggiuntivo: 500 crediti.`:'La sessione estiva riparte con 500 crediti alla prossima stagione.'}</div></section>`}
function tablePage(){let sorted=leagueTable(),me=currentClub();return `<div class="page-head"><div><div class="eyebrow">SERIE C · GRUPPO NAZIONALE</div><h1>Classifica</h1><p>Promozione diretta per la prima, playoff per le prime cinque.</p></div><div class="date-label">GIORNATA ${game.played} / 18</div></div><div class="content-grid"><section class="section-card"><table class="table standings-table"><thead><tr><th>#</th><th>Club</th><th>PG</th><th>V</th><th>N</th><th>P</th><th>DR</th><th>Pt</th></tr></thead><tbody>${sorted.map((t,i)=>`<tr class="${t.id===me.id?'my-team':''}"><td class="rank">${String(i+1).padStart(2,'0')}</td><td>${t.badge} ${t.name}</td><td>${t.p}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><strong>${t.pts}</strong></td></tr>`).join('')}</tbody></table><div class="muted" style="font-size:9px;margin-top:14px">1° promozione · 2°–5° playoff · 9°–10° retrocessione</div></section><aside><section class="section-card"><h2>La tua forma</h2><div style="font:500 27px var(--display);color:var(--lime)">${me.form.slice(-5).join(' · ')||'—'}</div><div class="muted" style="font-size:10px;margin-top:8px">${me.w} vittorie · ${me.d} pareggi · ${me.l} sconfitte</div></section><section class="section-card"><h2>Differenza reti</h2><div class="stat-value">${me.gf-me.ga>0?'+':''}${me.gf-me.ga}</div><div class="muted" style="font-size:10px">${me.gf} fatti · ${me.ga} subiti</div></section></aside></div>`}
function cupPage(){let cup=game.cup;if(!cup.entrants){let pool=game.teams.slice().sort((a,b)=>Math.random()-.5).slice(0,8);if(!pool.includes(currentClub()))pool[0]=currentClub();cup.entrants=pool.map(t=>t.id);cup.round=0;cup.results=[];save()}let names=['Quarti di finale','Semifinale','Finale'],round=cup.round;let rounds=[0,1,2].map(r=>`<div class="bracket-round"><h3>${names[r]}</h3>${r<round?(cup.results?.[r]||[]).map(x=>`<div class="bracket-match">${x}</div>`).join(''):r===round&&!cup.done?`<div class="bracket-match"><strong>Gara ${round+1}</strong><br>${cup.participants?.map(id=>game.teams.find(t=>t.id===id)?.name).join(' vs ')||'Sorteggio in corso'}</div>`:cup.done&&r===2?`<div class="bracket-match">🏆 ${cup.champion||'Coppa assegnata'}</div>`:`<div class="bracket-match muted">Da definire</div>`}</div>`).join('');return `<div class="page-head"><div><div class="eyebrow">TROFEO NAZIONALE · ELIMINAZIONE DIRETTA</div><h1>Coppa Italia Serie C</h1><p>Otto club, tre turni, un solo vincitore. La coppa può cambiare una stagione.</p></div><div class="date-label">${cup.done?'CONCLUSA':`TURNO ${cup.round+1} / 3`}</div></div><section class="section-card"><div class="cup-bracket">${rounds}</div></section><div class="content-grid"><section class="section-card"><h2>Il cammino</h2><div class="muted" style="font-size:11px;line-height:1.7">Vincere la Coppa Italia Serie C porta prestigio, una coppa in bacheca e slancio per il prossimo incarico. Le gare sono a eliminazione diretta.</div></section><aside class="section-card"><h2>${cup.done?'Coppa assegnata':'Prossimo turno'}</h2>${cup.done?`<div class="news-copy">${cup.champion===game.club?'🏆 La coppa è tua. Una notte indimenticabile.':`Vincitore: ${cup.champion}`}</div>`:`<div class="muted" style="font-size:10px;margin-bottom:12px">${cup.round===0?'Quarti di finale':cup.round===1?'Semifinale':'Finale'} · partita secca</div><button class="hero-cta" onclick="openCupMatch()">${cup.round===2?'GIOCA LA FINALE':'GIOCA LA COPPA'} ↗</button>`}</aside></div>`}
function newsPage(){let feed=game.news.map((n,i)=>`<article class="feed-post"><div class="feed-avatar">${n.icon}</div><div><div class="feed-author">${n.type==='club'?game.club+' Official':n.type==='transfer'?'Calciomercato Live':n.type==='social'?'Curva '+game.club:'Mondo Calcio'}<small>· ${n.date}</small></div><p>${n.text}</p><div class="feed-tags"><span class="feed-tag">#RoadToGlory</span><span>↗ condividi</span><span>♡ ${rnd(12,780)}</span></div></div></article>`).join('');return `<div class="page-head"><div><div class="eyebrow">SOCIAL · RISULTATI · MERCATO · PREMI</div><h1>Mondo Calcio</h1><p>Il calcio non si ferma mai. Le storie più calde, dentro e fuori dal campo.</p></div><div class="date-label">LIVE · ${game.season}</div></div><div class="content-grid"><section class="section-card news-feed" style="padding:0">${feed||'<div class="empty-state">Il mondo si sta svegliando…</div>'}</section><aside><section class="section-card"><h2>In tendenza</h2>${['#SerieC',' #Calciomercato',' #CoppeEuropee',' #PalloneDOro'].map((t,i)=>`<div class="fixture-row"><div class="fixture-date">0${i+1}</div><div class="fixture-teams"><strong>${t.trim()}</strong><div class="muted">${money(rnd(1,80))} mila post</div></div></div>`).join('')}</section><section class="section-card"><h2>Il tuo percorso</h2><div style="font:600 25px var(--display);color:var(--lime)">${game.trophies}</div><div class="muted" style="font-size:10px">Trofei · reputazione ${game.reputation}</div></section></aside></div>`}
function go(tab){activeTab=tab;render()}
function openMatch(){let f=nextFixture();if(!f)return endSeason();if(f.played)return toast('Questa giornata è già stata giocata.');let opp=opponentOf(f);game.match=buildMatch('league',opp,f);matchMode='normal';save();render()}
function buildMatch(type,opp,fixture){let club=currentClub(),home=type==='league'?fixture.home===club.id:Math.random()>.5,ownXI=club.players.filter(p=>p.starter&&!p.injury&&!p.bans),theirXI=opp.players.slice().sort((a,b)=>b.rating-a.rating).slice(0,11),ownPower=ownXI.reduce((a,p)=>a+p.rating*p.fitness/100,0)/Math.max(1,ownXI.length),oppPower=theirXI.reduce((a,p)=>a+p.rating,0)/11,diff=ownPower-oppPower+(home?3:-3),styleBonus=game.style==='Pressing alto'?1.5:game.style==='Possesso palla'?1:game.style==='Contropiede'?(home?0:1.6):game.style==='Difensivo'?-1:0;let ownG=sampleGoals(diff+styleBonus),oppG=sampleGoals(-diff-styleBonus),ownGoalPlayers=ownXI.filter(p=>p.pos==='ATT'||p.pos==='ALA'||p.pos==='CC'),oppGoalPlayers=theirXI.filter(p=>['ATT','ALA','CC'].includes(p.pos));let goals=[];for(let i=0;i<ownG;i++){let p=choice(ownGoalPlayers.length?ownGoalPlayers:ownXI);goals.push({minute:rnd(4,89),team:'own',player:p?.name||'Attaccante',text:`GOAL! ${p?.name||'Attaccante'} porta avanti ${game.club}.`})}for(let i=0;i<oppG;i++){let p=choice(oppGoalPlayers.length?oppGoalPlayers:theirXI);goals.push({minute:rnd(4,89),team:'opp',player:p?.name||'Attaccante',text:`Rete avversaria: ${p?.name||'Attaccante'} trova il varco.`})}goals.sort((a,b)=>a.minute-b.minute);let events=[...goals];for(let i=0;i<3;i++){let minute=rnd(7,86),lines=['Grande occasione: il portiere vola e devia in corner.','Conclusione dal limite, palla a lato di un soffio.','Intervento duro a centrocampo: l’arbitro richiama il capitano.','Cross teso in area, la difesa allontana in affanno.','Ripartenza fulminea, ma l’ultimo passaggio è impreciso.'];events.push({minute,team:'neutral',text:choice(lines)})}return{active:true,type,opp:opp.name,oppBadge:opp.badge,oppId:opp.id,fixture,home,score:[0,0],final:[ownG,oppG],events:events.sort((a,b)=>a.minute-b.minute),minute:0,log:[],substitutions:0,used:[],ownXI,oppXI,ownPower,oppPower,settled:false}}
function sampleGoals(power){let lambda=Math.max(.35,Math.min(3.2,1.3+power/10));let n=0,limit=Math.exp(-lambda),v=1;do{n++;v*=Math.random()}while(v>limit&&n<7);return n-1}
function matchHeader(){let m=game.match,first=m.home?`${game.club} ${game.clubIndex!==undefined?'':''}`:m.opp,second=m.home?m.opp:game.club;return `<div class="match-kicker">${m.type==='league'?`Serie C · Giornata ${game.round+1}`:'Coppa Italia Serie C · Gara secca'} · ${m.home?'IN CASA':'IN TRASFERTA'}</div><div class="match-teams"><div class="team-display"><div class="team-emoji">${m.home?CLUBS[game.clubIndex].badge:m.oppBadge}</div><strong>${first}</strong></div><div class="versus-big">${m.active&&m.minute>0?`<span class="result-score">${m.score[0]} – ${m.score[1]}</span>`:'VS'}${m.active&&m.minute>0?`<div class="muted" style="font-size:10px">${m.minute}'</div>`:''}</div><div class="team-display"><div class="team-emoji">${m.home?m.oppBadge:CLUBS[game.clubIndex].badge}</div><strong>${second}</strong></div></div>`}
function renderMatch(){let m=game.match,events=m.log||[];$('#app').innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand"><div class="brand-mark">↗</div><div class="brand-title">ROAD TO GLORY<span>LIVE MATCH CENTER</span></div></div><div class="season-pill">${m.type==='league'?'GIORNATA '+(game.round+1):'COPPA ITALIA'}</div><div class="top-actions"><button class="icon-btn" onclick="leaveMatch()" title="Esci">×</button></div></header><main class="main" style="max-width:1080px;margin:auto"><div class="page-head"><div><div class="eyebrow">${m.settled?'FISCHIO FINALE':'IL MOMENTO DELLA VERITÀ'}</div><h1>${m.settled?'Tabellino finale':'Match center'}</h1><p>${m.settled?'La partita è stata archiviata.':'Scegli il ritmo della simulazione e guida la squadra.'}</p></div><div class="date-label">${m.settled?'90′':`${m.minute}′ / 90′`}</div></div><section class="match-banner">${matchHeader()}${!m.started&&!m.settled?`<div class="match-options"><button class="mode-btn ${matchMode==='fast'?'active':''}" onclick="matchMode='fast';render()">⚡ Veloce</button><button class="mode-btn ${matchMode==='normal'?'active':''}" onclick="matchMode='normal';render()">◷ Normale</button><button class="mode-btn ${matchMode==='detailed'?'active':''}" onclick="matchMode='detailed';render()">◉ Super dettagliata</button></div><div class="muted" style="font-size:10px">${matchMode==='fast'?'Risultato immediato, marcatori e momenti chiave.':matchMode==='normal'?'Cronaca testuale, divisa tra primo e secondo tempo.':'Avanza a intervalli di 10 minuti. Cambia modulo e fai sostituzioni in partita.'}</div><button class="hero-cta mt-12" onclick="kickOff()">${matchMode==='detailed'?'ENTRA IN CAMPO':'CALCIO D’INIZIO'} ↗</button>`:m.started&&!m.settled?`<div class="result-score">${m.score[0]} – ${m.score[1]}</div><div class="match-options"><button class="mode-btn" onclick="openTacticalPause()">⚙ Cambia modulo</button><button class="mode-btn" onclick="openSubstitution()">⇄ Sostituzione (${m.substitutions}/5)</button><button class="hero-cta" onclick="advanceMatch()">AVANZA ${Math.min(10,90-m.minute)}′ ↗</button></div><div class="muted" style="font-size:10px">La partita è in pausa al ${m.minute}′. Le modifiche tattiche avranno effetto sulla squadra.</div>`:m.settled?`<div class="result-score">${m.score[0]} – ${m.score[1]}</div><div class="match-result">${m.score[0]>m.score[1]?'VITTORIA':m.score[0]===m.score[1]?'PAREGGIO':'SCONFITTA'} · ${game.club} ${m.score[0]} – ${m.score[1]} ${m.opp}</div><button class="hero-cta" onclick="leaveMatch()">TORNA AL CENTRO COMANDO ↗</button>`:''}</section><div class="content-grid mt-12"><section class="section-card"><div class="card-title"><h2>Cronaca</h2><span class="tag">${m.settled?'FINALE':m.started?`${m.minute}′ LIVE`:'PREPARTITA'}</span></div><div class="match-log">${events.length?events.map(e=>`<div class="log-line"><span class="log-time">${e.minute?`${e.minute}′`:'INFO'}</span>${e.text}</div>`).join(''):`<div class="empty-state" style="padding:15px">${m.started?'La gara è cominciata.':'La squadra si prepara nel tunnel…'}</div>`}</div></section><aside><section class="section-card"><h2>XI iniziale</h2>${m.ownXI.map(p=>`<div class="fixture-row"><div class="pos-chip">${p.pos}</div><div class="fixture-teams"><strong>${p.name}</strong><span class="muted"> · ${p.rating} OVR</span></div></div>`).join('')}</section>${m.started&&!m.settled?`<section class="section-card"><h2>Gestione in gara</h2><div class="muted" style="font-size:10px;line-height:1.7">Modulo: <strong>${game.formation}</strong><br>Stile: <strong>${game.style}</strong><br>Cambi effettuati: <strong>${m.substitutions}/5</strong></div></section>`:''}</aside></div></main></div>`}
function kickOff(){let m=game.match;m.started=true;if(matchMode==='fast'){m.log=m.events.filter(e=>e.team!=='neutral'||Math.random()>.45);m.minute=90;m.score=[m.final[0],m.final[1]];completeMatch()}else if(matchMode==='normal'){m.log.push({minute:0,text:`L’arbitro fischia l’inizio. ${game.club} affronta ${m.opp}.`});m.events.forEach(e=>{if(e.team==='own')m.score[0]++;else if(e.team==='opp')m.score[1]++;m.log.push(e)});m.log.sort((a,b)=>a.minute-b.minute);m.log.splice(Math.ceil(m.log.length/2),0,{minute:45,text:'INTERVALLO. Le squadre rientrano negli spogliatoi.'});m.log.push({minute:90,text:'Triplice fischio! La partita è terminata.'});m.minute=90;m.score=[m.final[0],m.final[1]];completeMatch()}else{m.log.push({minute:0,text:'Si parte! La tensione è palpabile.'});advanceMatch()}save();render()}
function advanceMatch(){let m=game.match,from=m.minute,to=Math.min(90,from+10);m.minute=to;m.events.filter(e=>e.minute>from&&e.minute<=to).forEach(e=>{m.log.push(e);if(e.team==='own')m.score[0]++;if(e.team==='opp')m.score[1]++});if(to===45)m.log.push({minute:45,text:'INTERVALLO. È il momento di riordinare le idee.'});if(to===90){m.log.push({minute:90,text:'Triplice fischio! La partita è terminata.'});completeMatch()}save();render()}

function recordResult(team,forGoals,againstGoals){team.p++;team.gf+=forGoals;team.ga+=againstGoals;if(forGoals>againstGoals){team.w++;team.pts+=3;team.form.push('V')}else if(forGoals===againstGoals){team.d++;team.pts++;team.form.push('N')}else{team.l++;team.form.push('P')}team.form=team.form.slice(-8)}
function settleMatchAvailability(m,club,opp,league=false){club.players.forEach(p=>{p.fitness=Math.max(40,p.fitness-rnd(9,17));if(p.injury>0)p.injury--;if(p.bans>0)p.bans--;if(m.ownXI.some(x=>x.id===p.id)){if(Math.random()<.12){p.yellows=(p.yellows||0)+1;if(p.yellows>=5){p.bans=1;p.yellows=0;addNews('🟨',`${p.name} è squalificato per la prossima gara.`,'club')}}if(Math.random()<.035){p.injury=rnd(1,3);p.starter=false;addNews('🩹',`${p.name} si ferma per ${p.injury} giornate.`,'club')}}});if(league)game.teams.filter(t=>t!==club).forEach(t=>t.players.forEach(p=>{if(p.injury>0)p.injury--;if(p.bans>0)p.bans--;p.fitness=Math.min(100,p.fitness+rnd(2,7))}));else if(opp)opp.players.forEach(p=>{if(p.injury>0)p.injury--;if(p.bans>0)p.bans--;p.fitness=Math.min(100,p.fitness+rnd(2,7))})}
function updateJobSecurity(own,against){let position=leagueTable().findIndex(t=>t.id===currentClub().id)+1,target=goalTarget(),change=own>against?5:own===against?-2:-8;if(position>target+2)change-=3;else if(position<=target)change+=2;game.jobSecurity=Math.max(0,Math.min(100,(game.jobSecurity??100)+change));if(game.jobSecurity===0&&!game.dismissed){game.dismissed=true;addNews('📉',`${game.club} esonera ${game.manager}: concluderai la stagione da traghettatore.`,'club')}}
function recordMatchGoals(m,club,opp){for(const e of m.events||[]){if(e.team==='own'){let p=club.players.find(x=>x.name===e.player);if(p)p.goals=(p.goals||0)+1}else if(e.team==='opp'){let p=opp?.players.find(x=>x.name===e.player);if(p)p.goals=(p.goals||0)+1}}}
function settlePlayerMatch(m){let club=currentClub(),opp=game.teams.find(t=>t.id===m.oppId),own=m.score[0],against=m.score[1];m.settled=true;m.minute=90;
 if(m.type==='league'&&!m.fixture.played){m.fixture.played=true;m.fixture.score=m.fixture.home===club.id?[own,against]:[against,own];recordResult(club,own,against);recordResult(opp,against,own);game.played++;game.round++;game.won+=own>against?1:0;game.drawn+=own===against?1:0;game.lost+=own<against?1:0;
  for(const fixture of game.schedule[game.round-1]||[]){if(fixture===m.fixture||fixture.played)continue;let h=game.teams.find(t=>t.id===fixture.home),a=game.teams.find(t=>t.id===fixture.away),hg=sampleGoals((h.level-a.level+2)/2),ag=sampleGoals((a.level-h.level-2)/2);fixture.played=true;fixture.score=[hg,ag];recordResult(h,hg,ag);recordResult(a,ag,hg)}
  game.credits+=own>against?45:own===against?25:12;recordMatchGoals(m,club,opp);settleMatchAvailability(m,club,opp,true);updateJobSecurity(own,against);
  if(own>against){game.reputation=Math.min(100,game.reputation+1);addNews('⚽',`${game.club} supera ${opp.name} ${own}–${against} e sale in classifica.`,'social')}else if(own<against)addNews('⚽',`${game.club} cade contro ${opp.name}: ${own}–${against}. La pressione aumenta.`,'social');else addNews('🤝',`${game.club} pareggia ${own}–${against} contro ${opp.name}.`,'social');
  if(game.round===9&&game.window==='estiva'){game.window='invernale';game.credits+=500;game.marketPool=null;addNews('💶','Apre il mercato invernale: 500 crediti aggiunti al budget.','transfer')}
  simulateWorldNews();
 }else if(m.type==='cup'){recordMatchGoals(m,club,opp);settleMatchAvailability(m,club,opp);settleCupMatch(m,own,against)}
 game.lastMatch={type:m.type,opponent:opp?.name||m.opp,score:[own,against],round:game.round};game.match.active=true;save()}
function completeMatch(){let m=game.match;if(!m||m.settled)return;settlePlayerMatch(m);render()}
function leaveMatch(){if(!game.match?.settled){toast('La gara è in corso: completala prima di uscire.');return}game.match=null;activeTab='overview';save();render()}
function ensureCup(){let c=game.cup;if(c.rounds)return c;let entrants=game.teams.slice().sort(()=>Math.random()-.5).slice(0,8);if(!entrants.includes(currentClub()))entrants[0]=currentClub();c.entrants=entrants.map(t=>t.id);c.round=0;c.rounds=[Array.from({length:4},(_,i)=>({a:c.entrants[i*2],b:c.entrants[i*2+1]}))];c.results=[];c.done=false;return c}
function openCupMatch(){let c=ensureCup();if(c.done)return toast('La Coppa è già conclusa.');if(c.round>=3)return toast('Turno non disponibile.');let pair=c.rounds[c.round]?.find(x=>x.a===currentClub().id||x.b===currentClub().id);if(!pair)return toast('La tua squadra è stata eliminata dalla Coppa.');if(pair.done)return toast('Questo turno è già stato giocato.');let opp=game.teams.find(t=>t.id===(pair.a===currentClub().id?pair.b:pair.a));game.match=buildMatch('cup',opp,null);game.match.cupPair=pair;matchMode='normal';save();render()}
function settleCupMatch(m,own,against){let c=ensureCup(),pair=m.cupPair||c.rounds[c.round]?.find(x=>x.a===currentClub().id||x.b===currentClub().id);if(!pair||pair.done)return;let userWon=own===against?Math.random()>.5:own>against,winner=userWon?currentClub().id:m.oppId;pair.done=true;pair.winner=winner;pair.score=[own,against];let name=id=>game.teams.find(t=>t.id===id)?.name||id;for(const other of c.rounds[c.round]){if(other.done)continue;let a=game.teams.find(t=>t.id===other.a),b=game.teams.find(t=>t.id===other.b),x=sampleGoals((a.level-b.level)/2),y=sampleGoals((b.level-a.level)/2);if(x===y)x++;other.score=[x,y];other.winner=x>y?a.id:b.id;other.done=true}
 c.results[c.round]=c.rounds[c.round].map(x=>`${name(x.a)} ${x.score[0]}–${x.score[1]} ${name(x.b)} · ${name(x.winner)} passa`);if(c.round===2){c.done=true;c.champion=name(c.rounds[2][0].winner);if(c.champion===game.club){game.trophies++;game.prestige=Math.min(5,game.prestige+1);game.credits+=200;game.reputation=Math.min(100,game.reputation+8);addNews('🏆',`${game.club} conquista la Coppa Italia Serie C!`,'club')}else addNews('🏆',`${c.champion} vince la Coppa Italia Serie C.`,'world')}else{let winners=c.rounds[c.round].map(x=>x.winner);c.round++;c.rounds[c.round]=Array.from({length:winners.length/2},(_,i)=>({a:winners[i*2],b:winners[i*2+1]}))}save()}
function simulateWorldNews(){if(Math.random()<.28){let t=choice(game.teams.filter(x=>x!==currentClub()));addNews('↗️',`${t.name} lavora sul mercato per rinforzare la rosa.`,'transfer')}if(Math.random()<.12){let p=choice(currentClub().players);p.assists=(p.assists||0)+1}}
function openTacticalPause(){let options=Object.keys(FORMATIONS).map(f=>`<button class="mode-btn ${game.formation===f?'active':''}" onclick="game.formation='${f}';save();render();$('#modal-root')?.remove()">${f}</button>`).join('');showModal(`<div class="card-title"><h2>Lavagna tattica</h2><button class="icon-btn" onclick="$('#modal-root').remove()">×</button></div><p class="muted">Scegli un modulo: influenza il piano gara dal prossimo intervallo.</p><div class="match-options">${options}</div><div class="control-row mt-12"><label class="label-small">Stile di gioco</label><select class="select-control" onchange="game.style=this.value;save()">${['Equilibrato','Possesso palla','Contropiede','Pressing alto','Difensivo'].map(s=>`<option ${game.style===s?'selected':''}>${s}</option>`).join('')}</select></div>`)}
function openSubstitution(){let m=game.match;if(m.substitutions>=5)return toast('Hai già effettuato cinque cambi.');let starters=m.ownXI.filter(p=>!m.used.includes(p.id)),bench=currentClub().players.filter(p=>!m.ownXI.some(x=>x.id===p.id)&&!p.injury&&!p.bans&&!m.used.includes(p.id));if(!starters.length||!bench.length)return toast('Non ci sono cambi disponibili.');showModal(`<div class="card-title"><h2>Sostituzione</h2><button class="icon-btn" onclick="$('#modal-root').remove()">×</button></div><p class="muted">Un cambio effettuato · ${m.substitutions}/5</p><div class="two-col"><label>Esce<select id="sub-out" class="select-control">${starters.map(p=>`<option value="${p.id}">${p.pos} · ${p.name} (${p.rating})</option>`).join('')}</select></label><label>Entra<select id="sub-in" class="select-control">${bench.map(p=>`<option value="${p.id}">${p.pos} · ${p.name} (${p.rating})</option>`).join('')}</select></label></div><button class="hero-cta mt-12" onclick="makeSubstitution()">CONFERMA CAMBIO ↗</button>`)}
function makeSubstitution(){let m=game.match,club=currentClub(),out=club.players.find(p=>p.id===$('#sub-out')?.value),incoming=club.players.find(p=>p.id===$('#sub-in')?.value);if(!out||!incoming||m.substitutions>=5)return;out.starter=false;incoming.starter=true;incoming.fitness=Math.max(40,incoming.fitness-3);m.ownXI=m.ownXI.filter(p=>p.id!==out.id);m.ownXI.push(incoming);m.used.push(out.id,incoming.id);m.substitutions++;m.ownPower=m.ownXI.reduce((a,p)=>a+p.rating*p.fitness/100,0)/Math.max(1,m.ownXI.length);$('#modal-root')?.remove();m.log.push({minute:m.minute,text:`Cambio: ${incoming.name} prende il posto di ${out.name}.`});save();render()}
function endSeason(){if(game.round<18)return toast('Completa tutte le 18 giornate prima di chiudere la stagione.');if(game.seasonClosed)return toast('La stagione è già stata conclusa.');let table=leagueTable(),position=table.findIndex(t=>t.id===currentClub().id)+1,target=goalTarget(),success=position<=target;game.seasonClosed=true;game.objectiveMet=success;game.reputation=Math.max(1,Math.min(100,game.reputation+(success?8:-6)));if(success){game.prestige=Math.min(5,game.prestige+(position===1?1:0));game.credits+=position===1?300:position<=5?180:80;addNews('🎯',`${game.club} raggiunge l’obiettivo: ${game.objectives}.`,'club')}else{game.credits+=35;addNews('📉',`Obiettivo mancato: ${game.club} chiude al ${position}° posto.`,'club')}
 let offers=CLUBS.filter(c=>c.name!==game.club&&c.prestige<=Math.max(1,Math.ceil(game.reputation/20)+1)).slice(0,3);if(game.dismissed){offers=CLUBS.filter(c=>c.name!==game.club).sort((a,b)=>Math.abs(a.prestige-game.prestige)-Math.abs(b.prestige-game.prestige)).slice(0,3)}else if(success&&position<=2){let stronger=CLUBS.filter(c=>c.name!==game.club&&c.prestige>=game.prestige);offers=[...new Map([...stronger,...offers].map(c=>[c.name,c])).values()].slice(0,3)}game.careerOffers=offers;game.history.push({season:game.season,club:game.club,position,points:currentClub().pts,objective:success});game.history=game.history.slice(-12);let top=game.teams.flatMap(t=>t.players.map(p=>({...p,club:t.name}))).sort((a,b)=>b.goals-a.goals)[0];if(top?.goals)addNews('🥇',`${top.name} è capocannoniere con ${top.goals} reti.`,'world');save();let offerHTML=offers.map((c,i)=>`<button class="team-pick" onclick="startNextSeason(${CLUBS.indexOf(c)})"><div class="pick-name">${c.badge} ${c.name}</div><div class="pick-league">Prestigio ${'★'.repeat(c.prestige)} · Budget 500 cr</div><div class="pick-stats"><span>INCARICO<strong>${c.target}</strong></span><span>ROSA<strong>${c.level} / 100</strong></span></div></button>`).join('');showModal(`<div class="eyebrow">STAGIONE ${game.season} CONCLUSA · ${position}° POSTO</div><h2 style="font:600 28px var(--display)">${success?'Obiettivo centrato!':'La prossima sfida ti aspetta'}</h2><p class="muted">${game.club}: ${currentClub().pts} punti. Reputazione: ${game.reputation}. ${game.cup.done?`Coppa vinta da ${game.cup.champion}.`:''}</p><div class="section-card"><h3>Offerte in carriera</h3>${offerHTML||'<p class="muted">Nessuna offerta: puoi restare e ricostruire.</p>'}<button class="mode-btn mt-12" onclick="startNextSeason(${game.clubIndex})">Resta al ${game.club} ↗</button></div><button class="text-link mt-12" onclick="$('#modal-root').remove();render()">Continua a valutare</button>`)}
function startNextSeason(index){let old=game,club=CLUBS[index]||CLUBS[old.clubIndex],teams=makeLeague(club),me=teams[0];old.season++;old.club=club.name;old.clubIndex=index;old.teams=teams;old.schedule=createSchedule(teams);old.round=0;old.played=old.won=old.drawn=old.lost=0;old.jobSecurity=100;old.dismissed=false;old.credits=Math.max(100,old.credits);old.initialBudget=old.credits;old.prestige=Math.max(old.prestige,club.prestige);old.objectives=club.target;old.objectiveMet=false;old.seasonClosed=false;old.formation='4-3-3';old.style='Equilibrato';old.captain=me.players[5].id;old.squad=me.players;old.cup={round:0,done:false,champion:null,fixtures:[]};old.window='estiva';old.marketPool=null;old.marketPoolKey='';old.match=null;old.news.unshift({icon:'📋',text:`${club.name} presenta ${old.manager} per la stagione ${old.season}.`,'date':`${old.season} · PRESEASON`,'type':'club'});old.news=old.news.slice(0,32);old.teams.forEach(t=>t.players.forEach(p=>{p.fitness=100;p.injury=0;p.bans=0;p.yellows=0;p.goals=0;p.assists=0}));save();$('#modal-root')?.remove();activeTab='overview';render();toast(`Una nuova stagione ti aspetta al ${club.name}.`)}
function cupPage(){let cup=ensureCup(),names=['Quarti di finale','Semifinale','Finale'],round=cup.round;let rounds=[0,1,2].map(r=>`<div class="bracket-round"><h3>${names[r]}</h3>${r<round?(cup.results?.[r]||[]).map(x=>`<div class="bracket-match">${x}</div>`).join(''):r===round&&!cup.done?(cup.rounds[r]||[]).map(x=>`<div class="bracket-match">${game.teams.find(t=>t.id===x.a)?.name} vs ${game.teams.find(t=>t.id===x.b)?.name}${x.done?' · giocata':''}</div>`).join('')||'<div class="bracket-match">Sorteggio in corso</div>':cup.done&&r===2?`<div class="bracket-match">🏆 ${cup.champion||'Coppa assegnata'}</div>`:'<div class="bracket-match muted">Da definire</div>'}</div>`).join('');let eliminated=!cup.done&&!cup.rounds[cup.round]?.some(x=>x.a===currentClub().id||x.b===currentClub().id);return `<div class="page-head"><div><div class="eyebrow">TROFEO NAZIONALE · ELIMINAZIONE DIRETTA</div><h1>Coppa Italia Serie C</h1><p>Otto club, tre turni, un solo vincitore. La coppa può cambiare una stagione.</p></div><div class="date-label">${cup.done?'CONCLUSA':`TURNO ${cup.round+1} / 3`}</div></div><section class="section-card"><div class="cup-bracket">${rounds}</div></section><div class="content-grid"><section class="section-card"><h2>Il cammino</h2><div class="muted" style="font-size:11px;line-height:1.7">Vincere la Coppa Italia Serie C porta prestigio, una coppa in bacheca e slancio per il prossimo incarico. Le gare sono a eliminazione diretta.</div></section><aside class="section-card"><h2>${cup.done?'Coppa assegnata':'Prossimo turno'}</h2>${cup.done?`<div class="news-copy">${cup.champion===game.club?'🏆 La coppa è tua. Una notte indimenticabile.':`Vincitore: ${cup.champion}`}</div>`:eliminated?'<div class="muted">La tua squadra è stata eliminata.</div>':`<div class="muted" style="font-size:10px;margin-bottom:12px">${names[cup.round]} · partita secca</div><button class="hero-cta" onclick="openCupMatch()">${cup.round===2?'GIOCA LA FINALE':'GIOCA LA COPPA'} ↗</button>`}</aside></div>`}

render();
